import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Input blocks","description":"Configure form field blocks on pages.","frontmatter":{"title":"Input blocks","description":"Configure form field blocks on pages."},"headers":[],"relativePath":"en/seiten/eingabebloecke.md","filePath":"en/seiten/eingabebloecke.md","lastUpdated":1787319236000}'),s={name:"en/seiten/eingabebloecke.md"};function i(n,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="input-blocks" tabindex="-1">Input blocks <a class="header-anchor" href="#input-blocks" aria-label="Permalink to &quot;Input blocks&quot;">​</a></h1><p>Pages have the same input fields as <a href="/en/formulare/felder-konfigurieren">forms</a> — but here freely placeable, combinable with text and layout, and with <a href="/en/seiten/sichtbarkeit">conditional visibility</a>.</p><h2 id="shared-settings" tabindex="-1">Shared settings <a class="header-anchor" href="#shared-settings" aria-label="Permalink to &quot;Shared settings&quot;">​</a></h2><p>Every input block has under <strong>Field settings</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Required field</strong></td><td>No submission without input. Error: <em>This field is required</em></td></tr><tr><td><strong>Not editable</strong></td><td>Shown but can&#39;t be edited</td></tr><tr><td><strong>Color</strong></td><td>Field styling</td></tr><tr><td><strong>Key</strong></td><td>The field&#39;s technical identifier</td></tr></tbody></table><h3 id="the-key" tabindex="-1">The Key <a class="header-anchor" href="#the-key" aria-label="Permalink to &quot;The Key&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">The key is the link to Flows and visibility</p><p>The interface explains it as: <em>Used to reference this field in workflows and form values.</em></p><p>Concretely, you&#39;ll need it in two places:</p><ul><li>in <a href="/en/seiten/sichtbarkeit">conditional visibility</a>, e.g. <code>formValues.get(&#39;age&#39;)</code></li><li>in <a href="/en/flows/daten-zwischen-schritten">Flows</a>, when the page passes data to a workflow</li></ul><p>Choose descriptive keys like <code>age</code> or <code>department</code> before you start using them — changing them afterward breaks existing conditions.</p></div><p>Use <strong>Manage keys</strong> to see all keys of a page at once.</p><hr><h2 id="text-fields" tabindex="-1">Text fields <a class="header-anchor" href="#text-fields" aria-label="Permalink to &quot;Text fields&quot;">​</a></h2><p><strong>Single-line</strong> and <strong>Multi-line text field</strong> support the same <a href="/en/grids/eintraege#emoticon-shortcuts">emoticon shortcuts</a> as Grid text cells: <code>(/)</code> becomes ✅, <code>(x)</code> becomes ❌, <code>(Y)</code> becomes 👍, and so on.</p><hr><h2 id="rating-scale" tabindex="-1">Rating scale <a class="header-anchor" href="#rating-scale" aria-label="Permalink to &quot;Rating scale&quot;">​</a></h2><p>Captures ratings as a number, with five possible display styles.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Options</th></tr></thead><tbody><tr><td><strong>Style</strong></td><td><em>NPS scale</em>, <em>Segmented</em>, <em>Stars</em>, <em>Emoji</em>, <em>Slider</em></td></tr><tr><td><strong>Minimum</strong> / <strong>Maximum</strong></td><td>Value range</td></tr><tr><td><strong>Step</strong></td><td>Interval between values</td></tr><tr><td><strong>Minimum label</strong> / <strong>Maximum label</strong></td><td>Text at each end</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Choose a style by purpose</p><ul><li><strong>Stars</strong> — familiar for product and service ratings</li><li><strong>Emoji</strong> — low-barrier, good for quick feedback</li><li><strong>NPS scale</strong> — the established 0-to-10 layout for recommendation questions</li><li><strong>Segmented</strong> — neutral, works well with end labels</li><li><strong>Slider</strong> — for larger value ranges</li></ul><p>The end labels are almost always worth adding: &quot;not at all&quot; to &quot;completely&quot; turns abstract numbers into an understandable question.</p></div><p>If nothing is entered: <em>Please select a value</em>.</p><hr><h2 id="checkmark" tabindex="-1">Checkmark <a class="header-anchor" href="#checkmark" aria-label="Permalink to &quot;Checkmark&quot;">​</a></h2><p>In addition to the shared settings:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Must be checked</strong></td><td>The checkmark has to be set</td></tr><tr><td><strong>Color</strong></td><td>Appearance</td></tr></tbody></table><p>Error: <em>This field must be checked</em> or <em>{Label} must be checked</em>.</p><div class="tip custom-block"><p class="custom-block-title">For consent</p><p><em>Must be checked</em> is what distinguishes this from a regular required field: a checkmark as a required field would still be satisfied by &quot;unchecked.&quot; For agreeing to terms or privacy notices, you need this setting.</p></div><hr><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Shows a Yes/No choice as cards and stores it as a boolean value.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Yes label</strong></td><td>Text of the accept card</td></tr><tr><td><strong>No label</strong></td><td>Text of the decline card</td></tr></tbody></table><p>Error: <em>Please make a selection</em>.</p><div class="tip custom-block"><p class="custom-block-title">Clearer than a checkmark</p><p>For deliberate decisions — &quot;confirm attendance&quot; / &quot;decline&quot; — this block is clearer than a checkmark, because both options are visible and neither is preselected.</p></div><hr><h2 id="upload-files-or-photos" tabindex="-1">Upload files or photos <a class="header-anchor" href="#upload-files-or-photos" aria-label="Permalink to &quot;Upload files or photos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Maximum number of files</strong></td><td><em>Leave empty for unlimited</em></td></tr><tr><td><strong>Restrict upload to file type</strong></td><td>Restricts the allowed types</td></tr><tr><td><strong>Allowed file types</strong></td><td><em>All</em>, <em>PDF</em>, <em>Image</em>, <em>PNG</em>, <em>JPEG</em>, <em>CSV</em></td></tr><tr><td><strong>Allow adding files only</strong></td><td>Existing attachments can&#39;t be deleted</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Restricting types avoids follow-up questions</p><p>If you need a PDF, set the type to <em>PDF</em>. Otherwise you&#39;ll get screenshots, Word files, and photos of the screen.</p><p>The maximum file size is plan-dependent and can&#39;t be changed here.</p></div><hr><h2 id="recording-blocks" tabindex="-1">Recording blocks <a class="header-anchor" href="#recording-blocks" aria-label="Permalink to &quot;Recording blocks&quot;">​</a></h2><p><strong>Voice recording</strong>, <strong>Upload video</strong>, and <strong>Photo camera</strong> capture directly through the device.</p><p>For video and photo, <strong>Edit instruction</strong> lets you add a hint that appears during recording. For photo, there&#39;s also <strong>Add timestamp</strong> and <strong>Button color</strong>.</p><p>Controls: <em>START</em>, <em>PAUSE</em>, <em>NEXT</em>, <em>Done</em>. Without permission: <em>Please allow access to the microphone</em>.</p><div class="tip custom-block"><p class="custom-block-title">Timestamp for documentation</p><p>For construction site, damage, and maintenance documentation, <em>Add timestamp</em> is useful — the recording date is then embedded in the image itself.</p></div><hr><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2><p>The video block can be made mandatory:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Watch to the end</strong></td><td>Can&#39;t proceed until the video has played fully</td></tr></tbody></table><p>Notice for visitors: <em>Please watch the video to the end.</em></p><div class="tip custom-block"><p class="custom-block-title">For training material</p><p>Combined with the <a href="/en/seiten/layout-bloecke">Stepper layout</a> and a checkmark set to <em>Must be checked</em>, you can build a simple briefing: watch the video, confirm acknowledgment, submit.</p></div><hr><h2 id="barcode-scanner" tabindex="-1">Barcode scanner <a class="header-anchor" href="#barcode-scanner" aria-label="Permalink to &quot;Barcode scanner&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Show text field</strong></td><td>Also allows manual entry</td></tr><tr><td><strong>Button color</strong></td><td>Appearance</td></tr></tbody></table><p>Placeholder: <em>Enter code manually or scan</em>. Without a value: <em>No value scanned</em>.</p><p>Camera error messages:</p><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th></tr></thead><tbody><tr><td><em>Camera permission denied. Please allow camera access in your browser settings.</em></td><td>Access declined</td></tr><tr><td><em>No camera found. Please connect a camera to your device.</em></td><td>No device</td></tr><tr><td><em>Camera is already in use by another application.</em></td><td>In use</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Always leave the text field enabled</p><p>Cameras fail: poor lighting, a damaged code, missing permission. With <em>Show text field</em>, the person can type the number in as a fallback instead of abandoning the process.</p></div><hr><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/referenz/blocktypen">Block types reference</a></li><li><a href="/en/seiten/sichtbarkeit">Conditional visibility</a></li><li><a href="/en/seiten/layout-bloecke">Layout blocks</a></li></ul>',55)])])}const b=t(s,[["render",i]]);export{p as __pageData,b as default};
